CREATE TABLE "events" ("id" UUID NOT NULL,"title" VARCHAR(180) NOT NULL,"slug" VARCHAR(200) NOT NULL,"description" VARCHAR(5000) NOT NULL,"location" VARCHAR(240) NOT NULL,"start_date" TIMESTAMP(3) NOT NULL,"end_date" TIMESTAMP(3) NOT NULL,"capacity" INTEGER,"registration_enabled" BOOLEAN NOT NULL DEFAULT true,"is_published" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "events_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "events_slug_key" ON "events"("slug");CREATE INDEX "events_start_date_idx" ON "events"("start_date");CREATE INDEX "events_is_published_idx" ON "events"("is_published");
CREATE TABLE "event_registrations" ("id" UUID NOT NULL,"event_id" UUID NOT NULL,"contact_id" UUID NOT NULL,"registered_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"status" VARCHAR(20) NOT NULL DEFAULT 'Registered',"notes" VARCHAR(2000),CONSTRAINT "event_registrations_pkey" PRIMARY KEY ("id"),CONSTRAINT "event_registrations_event_id_fkey" FOREIGN KEY ("event_id") REFERENCES "events"("id") ON DELETE CASCADE,CONSTRAINT "event_registrations_contact_id_fkey" FOREIGN KEY ("contact_id") REFERENCES "contacts"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "event_registrations_event_id_contact_id_key" ON "event_registrations"("event_id","contact_id");CREATE INDEX "event_registrations_event_id_idx" ON "event_registrations"("event_id");CREATE INDEX "event_registrations_contact_id_idx" ON "event_registrations"("contact_id");
